<?php
require_once __DIR__.'/../includes/bootstrap.php';require_role('admin');
if($_SERVER['REQUEST_METHOD']==='POST'){try{$kind=$_POST['kind'];$section=(int)$_POST['section_id'];$q=$conn->prepare('SELECT school_year_id,grade_level FROM sections WHERE section_id=?');$q->bind_param('i',$section);$q->execute();$sectionInfo=$q->get_result()->fetch_assoc();if(!$sectionInfo||(int)$sectionInfo['school_year_id']!==(int)$_POST['school_year_id'])throw new RuntimeException('Section and school year must match.');if($kind==='teacher'){$teacher=(int)$_POST['teacher_id'];$subject=(int)$_POST['subject_id'];$year=(int)$sectionInfo['school_year_id'];$q=$conn->prepare('SELECT grade_level,strand_id FROM subjects WHERE subject_id=? AND status="active"');$q->bind_param('i',$subject);$q->execute();$subjectInfo=$q->get_result()->fetch_assoc();if(!$subjectInfo||$subjectInfo['grade_level']!==$sectionInfo['grade_level'])throw new RuntimeException('Subject and section grade levels must match.');$q=$conn->prepare('INSERT INTO teacher_assignments(teacher_id,subject_id,section_id,school_year_id) VALUES(?,?,?,?)');$q->bind_param('iiii',$teacher,$subject,$section,$year);$q->execute();}elseif($kind==='student'){$student=(int)$_POST['student_id'];$year=(int)$sectionInfo['school_year_id'];$q=$conn->prepare('INSERT INTO student_enrollments(student_id,section_id,school_year_id) VALUES(?,?,?) ON DUPLICATE KEY UPDATE section_id=VALUES(section_id),assignment_status="active"');$q->bind_param('iii',$student,$section,$year);$q->execute();}audit($conn,$_SESSION['user_id'],'assignment_'.$kind,'assignment');flash('Assignment saved.');}catch(Throwable $e){flash('Could not save assignment. Confirm the selected section, subject, and school year agree.','error');}go('/spi/admin/assignments.php');}
$years=$conn->query('SELECT * FROM school_years ORDER BY school_year_id DESC')->fetch_all(MYSQLI_ASSOC);$teachers=$conn->query("SELECT u.user_id,p.full_name FROM users u JOIN teacher_profiles p ON p.user_id=u.user_id WHERE u.role='teacher' AND u.account_status='active' ORDER BY p.full_name")->fetch_all(MYSQLI_ASSOC);$subjects=$conn->query("SELECT subject_id,subject_code,subject_name FROM subjects WHERE status='active' ORDER BY subject_name")->fetch_all(MYSQLI_ASSOC);$sections=$conn->query("SELECT s.section_id,s.section_name,s.grade_level,y.school_year_id,y.school_year_name,t.strand_code FROM sections s JOIN school_years y ON y.school_year_id=s.school_year_id JOIN strands t ON t.strand_id=s.strand_id WHERE s.status='active' ORDER BY y.school_year_id DESC,s.grade_level,s.section_name")->fetch_all(MYSQLI_ASSOC);$students=$conn->query("SELECT student_id,lrn,firstname,middle_name,lastname FROM students WHERE record_status='active' ORDER BY lastname,firstname")->fetch_all(MYSQLI_ASSOC);
page_start('Assignments');echo '<h1>Class assignments</h1><div class="grid"><section class="card"><h2>Assign teacher to subject and section</h2><form method="post"><input type="hidden" name="csrf" value="'.e(csrf_token()).'"><input type="hidden" name="kind" value="teacher"><label>Teacher<select name="teacher_id">';foreach($teachers as $x)echo '<option value="'.$x['user_id'].'">'.e($x['full_name']).'</option>';echo '</select></label><label>Subject<select name="subject_id">';foreach($subjects as $x)echo '<option value="'.$x['subject_id'].'">'.e($x['subject_code'].' — '.$x['subject_name']).'</option>';echo '</select></label><label>Section and year<select name="section_id">';foreach($sections as $x)echo '<option value="'.$x['section_id'].'">'.e($x['school_year_name'].' · Grade '.$x['grade_level'].' · '.$x['strand_code'].' · '.$x['section_name']).'</option>';echo '</select></label><label>School year<select name="school_year_id">';foreach($years as $y)echo '<option value="'.$y['school_year_id'].'">'.e($y['school_year_name']).'</option>';echo '</select></label><button>Assign teacher</button></form></section><section class="card"><h2>Assign student to section</h2><form method="post"><input type="hidden" name="csrf" value="'.e(csrf_token()).'"><input type="hidden" name="kind" value="student"><label>Student<select name="student_id">';foreach($students as $x)echo '<option value="'.$x['student_id'].'">'.e($x['lrn'].' · '.$x['lastname'].', '.$x['firstname'].' '.$x['middle_name']).'</option>';echo '</select></label><label>Section<select name="section_id">';foreach($sections as $x)echo '<option value="'.$x['section_id'].'">'.e($x['school_year_name'].' · Grade '.$x['grade_level'].' · '.$x['strand_code'].' · '.$x['section_name']).'</option>';echo '</select></label><label>School year<select name="school_year_id">';foreach($years as $y)echo '<option value="'.$y['school_year_id'].'">'.e($y['school_year_name']).'</option>';echo '</select></label><button>Assign student</button></form></section></div>';page_end();
